\Big\{u^2\Big(|q_{s}(s)^{\rm{LL}}_{\rm{SM}}+q_{t}(s, \theta)^{\rm{LL}}_{\rm{SM}}|^2+|q_{s}(s)^{\rm{RR}}+q_{t}(s, \theta)^{\rm{RR}}|^2\Big)+2t^2 |q_s(s)^{\rm{LR}}_{\rm{SM}}|^2\Big\}}} \, , \\
